1753	// exact for normals/+-0; q1_0 scales never carry fp16 subnormals
1754	static inline vfloat32m4_t q1_expand_fp16_64_m4(const ggml_half * p) {
1755	    const size_t vl = 64;
1756	    const vuint32m4_t hz   = __riscv_vzext_vf2_u32m4(__riscv_vle16_v_u16m2((const uint16_t *) p, vl), vl);
1757	    const vuint32m4_t sign = __riscv_vsll_vx_u32m4(__riscv_vand_vx_u32m4(hz, 0x8000, vl), 16, vl);
1758	    vuint32m4_t       mag  = __riscv_vadd_vx_u32m4(
1759	        __riscv_vsll_vx_u32m4(__riscv_vand_vx_u32m4(hz, 0x7FFF, vl), 13, vl), (uint32_t) 112 << 23, vl);
1760	    const vbool8_t ez = __riscv_vmseq_vx_u32m4_b8(__riscv_vand_vx_u32m4(hz, 0x7C00, vl), 0, vl);
1761	    mag               = __riscv_vmerge_vxm_u32m4(mag, 0, ez, vl);
1762	    return __riscv_vreinterpret_v_u32m4_f32m4(__riscv_vor_vv_u32m4(sign, mag, vl));
1763	}
