1765	static inline vfloat32m2_t q1_expand_fp16_64_m2(const ggml_half * p) {
1766	    const size_t vl = 64;
1767	    const vuint32m2_t hz   = __riscv_vzext_vf2_u32m2(__riscv_vle16_v_u16m1((const uint16_t *) p, vl), vl);
1768	    const vuint32m2_t sign = __riscv_vsll_vx_u32m2(__riscv_vand_vx_u32m2(hz, 0x8000, vl), 16, vl);
1769	    vuint32m2_t       mag  = __riscv_vadd_vx_u32m2(
1770	        __riscv_vsll_vx_u32m2(__riscv_vand_vx_u32m2(hz, 0x7FFF, vl), 13, vl), (uint32_t) 112 << 23, vl);
1771	    const vbool16_t ez = __riscv_vmseq_vx_u32m2_b16(__riscv_vand_vx_u32m2(hz, 0x7C00, vl), 0, vl);
1772	    mag                = __riscv_vmerge_vxm_u32m2(mag, 0, ez, vl);
1773	    return __riscv_vreinterpret_v_u32m2_f32m2(__riscv_vor_vv_u32m2(sign, mag, vl));
1774	}
