1776	static void q1_gemv_64x1_vl512(int n, float * s, const void * vx, const block_q8_0 * a_ptr, int nc) {
1777	    const int    nb = n / QK1_0;
1778	    const size_t vl = 64;
1779	    for (int x = 0; x < nc / 64; ++x) {
1780	        const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
1781	        vfloat32m4_t sumf = __riscv_vfmv_v_f_f32m4(0.0f, vl);
1782	        for (int l = 0; l < nb; ++l) {
1783	            q1_prefetch_block(bx, l, nb);
1784	            const vfloat32m4_t dx   = q1_expand_fp16_64_m4(bx[l].d);
1785	            vfloat32m4_t       facc = __riscv_vfmv_v_f_f32m4(0.0f, vl);
1786	            for (int k = 0; k < QK1_0 / QK8_0; ++k) {
1787	                const block_q8_0 * ab = &a_ptr[l * (QK1_0 / QK8_0) + k];
1788	                vint16m2_t sumi = __riscv_vmv_v_x_i16m2(0, vl);
1789	                for (int c = 0; c < QK8_0; ++c) {
1790	                    const int16_t  yc   = ab->qs[c];
1791	                    const vbool8_t sign = __riscv_vlm_v_b8(bx[l].qs[k * QK8_0 + c], vl);
1792	                    sumi = __riscv_vsub_vx_i16m2(sumi, yc, vl);
1793	                    sumi = __riscv_vadd_vx_i16m2_mu(sign, sumi, sumi, (int16_t) (2 * yc), vl);
1794	                }
1795	                facc = __riscv_vfmacc_vf_f32m4(facc, GGML_CPU_FP16_TO_FP32(ab->d),
1796	                    __riscv_vfcvt_f_x_v_f32m4(__riscv_vsext_vf2_i32m4(sumi, vl), vl), vl);
1797	            }
1798	            sumf = __riscv_vfmacc_vv_f32m4(sumf, dx, facc, vl);
1799	        }
1800	        __riscv_vse32_v_f32m4(s + (size_t) x * 64, sumf, vl);
1801	    }
1802	}
