1804	static void q1_gemv_64x1_vl1024(int n, float * s, const void * vx, const block_q8_0 * a_ptr, int nc) {
1805	    const int    nb = n / QK1_0;
1806	    const size_t vl = 64;
1807	    for (int x = 0; x < nc / 64; ++x) {
1808	        const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
1809	        vfloat32m2_t sumf = __riscv_vfmv_v_f_f32m2(0.0f, vl);
1810	        for (int l = 0; l < nb; ++l) {
1811	            q1_prefetch_block(bx, l, nb);
1812	            const vfloat32m2_t dx   = q1_expand_fp16_64_m2(bx[l].d);
1813	            vfloat32m2_t       facc = __riscv_vfmv_v_f_f32m2(0.0f, vl);
1814	            for (int k = 0; k < QK1_0 / QK8_0; ++k) {
1815	                const block_q8_0 * ab = &a_ptr[l * (QK1_0 / QK8_0) + k];
1816	                vint16m1_t sumi = __riscv_vmv_v_x_i16m1(0, vl);
1817	                for (int c = 0; c < QK8_0; ++c) {
1818	                    const int16_t   yc   = ab->qs[c];
1819	                    const vbool16_t sign = __riscv_vlm_v_b16(bx[l].qs[k * QK8_0 + c], vl);
1820	                    sumi = __riscv_vsub_vx_i16m1(sumi, yc, vl);
1821	                    sumi = __riscv_vadd_vx_i16m1_mu(sign, sumi, sumi, (int16_t) (2 * yc), vl);
1822	                }
1823	                facc = __riscv_vfmacc_vf_f32m2(facc, GGML_CPU_FP16_TO_FP32(ab->d),
1824	                    __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi, vl), vl), vl);
1825	            }
1826	            sumf = __riscv_vfmacc_vv_f32m2(sumf, dx, facc, vl);
1827	        }
1828	        __riscv_vse32_v_f32m2(s + (size_t) x * 64, sumf, vl);
1829	    }
1830	}
