1832	// gemm over the blck_size_interleave=1 x4 activation layout: qs[c*4+m], d[4].
1833	// M-tile = 4 at VLEN>=1024 (~25/32 regs), 2 at VLEN=512 (f32 accs are m4).
1834	
1835	static void q1_gemm_64x1_vl512(int n, float * s, size_t bs, const void * vx, const block_q8_0x4 * vy, int nr, int nc) {
1836	    const int    nb   = n / QK1_0;
1837	    const int    nbq8 = n / QK8_0;
1838	    const size_t vl   = 64;
1839	    for (int y = 0; y < nr / 4; ++y) {
1840	        const block_q8_0x4 * a_ptr = vy + (size_t) y * nbq8;
1841	        for (int x = 0; x < nc / 64; ++x) {
1842	            const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
1843	            for (int mh = 0; mh < 4; mh += 2) {
1844	                vfloat32m4_t sumf0 = __riscv_vfmv_v_f_f32m4(0.0f, vl);
1845	                vfloat32m4_t sumf1 = sumf0;
1846	                for (int l = 0; l < nb; ++l) {
1847	                    q1_prefetch_block(bx, l, nb);
1848	                    const vfloat32m4_t dx    = q1_expand_fp16_64_m4(bx[l].d);
1849	                    vfloat32m4_t       facc0 = __riscv_vfmv_v_f_f32m4(0.0f, vl);
1850	                    vfloat32m4_t       facc1 = facc0;
1851	                    for (int k = 0; k < QK1_0 / QK8_0; ++k) {
1852	                        const block_q8_0x4 * ab = &a_ptr[l * (QK1_0 / QK8_0) + k];
1853	                        vint16m2_t sumi0 = __riscv_vmv_v_x_i16m2(0, vl);
1854	                        vint16m2_t sumi1 = sumi0;
1855	                        for (int c = 0; c < QK8_0; ++c) {
1856	                            const vbool8_t sign = __riscv_vlm_v_b8(bx[l].qs[k * QK8_0 + c], vl);
1857	                            const int16_t  a0   = ab->qs[c * 4 + mh + 0];
1858	                            const int16_t  a1   = ab->qs[c * 4 + mh + 1];
1859	                            sumi0 = __riscv_vsub_vx_i16m2(sumi0, a0, vl);
1860	                            sumi0 = __riscv_vadd_vx_i16m2_mu(sign, sumi0, sumi0, (int16_t) (2 * a0), vl);
1861	                            sumi1 = __riscv_vsub_vx_i16m2(sumi1, a1, vl);
1862	                            sumi1 = __riscv_vadd_vx_i16m2_mu(sign, sumi1, sumi1, (int16_t) (2 * a1), vl);
1863	                        }
1864	                        facc0 = __riscv_vfmacc_vf_f32m4(facc0, GGML_CPU_FP16_TO_FP32(ab->d[mh + 0]),
1865	                            __riscv_vfcvt_f_x_v_f32m4(__riscv_vsext_vf2_i32m4(sumi0, vl), vl), vl);
1866	                        facc1 = __riscv_vfmacc_vf_f32m4(facc1, GGML_CPU_FP16_TO_FP32(ab->d[mh + 1]),
1867	                            __riscv_vfcvt_f_x_v_f32m4(__riscv_vsext_vf2_i32m4(sumi1, vl), vl), vl);
1868	                    }
1869	                    sumf0 = __riscv_vfmacc_vv_f32m4(sumf0, dx, facc0, vl);
1870	                    sumf1 = __riscv_vfmacc_vv_f32m4(sumf1, dx, facc1, vl);
1871	                }
1872	                __riscv_vse32_v_f32m4(s + (size_t) (y * 4 + mh + 0) * bs + (size_t) x * 64, sumf0, vl);
1873	                __riscv_vse32_v_f32m4(s + (size_t) (y * 4 + mh + 1) * bs + (size_t) x * 64, sumf1, vl);
1874	            }
1875	        }
1876	    }
1877	}
