1879	static void q1_gemm_64x1_vl1024(int n, float * s, size_t bs, const void * vx, const block_q8_0x4 * vy, int nr, int nc) {
1880	    const int    nb   = n / QK1_0;
1881	    const int    nbq8 = n / QK8_0;
1882	    const size_t vl   = 64;
1883	    for (int y = 0; y < nr / 4; ++y) {
1884	        const block_q8_0x4 * a_ptr = vy + (size_t) y * nbq8;
1885	        for (int x = 0; x < nc / 64; ++x) {
1886	            const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
1887	            vfloat32m2_t sumf0 = __riscv_vfmv_v_f_f32m2(0.0f, vl);
1888	            vfloat32m2_t sumf1 = sumf0, sumf2 = sumf0, sumf3 = sumf0;
1889	            for (int l = 0; l < nb; ++l) {
1890	                q1_prefetch_block(bx, l, nb);
1891	                const vfloat32m2_t dx    = q1_expand_fp16_64_m2(bx[l].d);
1892	                vfloat32m2_t       facc0 = __riscv_vfmv_v_f_f32m2(0.0f, vl);
1893	                vfloat32m2_t       facc1 = facc0, facc2 = facc0, facc3 = facc0;
1894	                for (int k = 0; k < QK1_0 / QK8_0; ++k) {
1895	                    const block_q8_0x4 * ab = &a_ptr[l * (QK1_0 / QK8_0) + k];
1896	                    vint16m1_t sumi0 = __riscv_vmv_v_x_i16m1(0, vl);
1897	                    vint16m1_t sumi1 = sumi0, sumi2 = sumi0, sumi3 = sumi0;
1898	                    for (int c = 0; c < QK8_0; ++c) {
1899	                        const vbool16_t sign = __riscv_vlm_v_b16(bx[l].qs[k * QK8_0 + c], vl);
1900	                        const int16_t   a0 = ab->qs[c * 4 + 0], a1 = ab->qs[c * 4 + 1];
1901	                        const int16_t   a2 = ab->qs[c * 4 + 2], a3 = ab->qs[c * 4 + 3];
1902	                        sumi0 = __riscv_vsub_vx_i16m1(sumi0, a0, vl);
1903	                        sumi0 = __riscv_vadd_vx_i16m1_mu(sign, sumi0, sumi0, (int16_t) (2 * a0), vl);
1904	                        sumi1 = __riscv_vsub_vx_i16m1(sumi1, a1, vl);
1905	                        sumi1 = __riscv_vadd_vx_i16m1_mu(sign, sumi1, sumi1, (int16_t) (2 * a1), vl);
1906	                        sumi2 = __riscv_vsub_vx_i16m1(sumi2, a2, vl);
1907	                        sumi2 = __riscv_vadd_vx_i16m1_mu(sign, sumi2, sumi2, (int16_t) (2 * a2), vl);
1908	                        sumi3 = __riscv_vsub_vx_i16m1(sumi3, a3, vl);
1909	                        sumi3 = __riscv_vadd_vx_i16m1_mu(sign, sumi3, sumi3, (int16_t) (2 * a3), vl);
1910	                    }
1911	                    facc0 = __riscv_vfmacc_vf_f32m2(facc0, GGML_CPU_FP16_TO_FP32(ab->d[0]),
1912	                        __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi0, vl), vl), vl);
1913	                    facc1 = __riscv_vfmacc_vf_f32m2(facc1, GGML_CPU_FP16_TO_FP32(ab->d[1]),
1914	                        __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi1, vl), vl), vl);
1915	                    facc2 = __riscv_vfmacc_vf_f32m2(facc2, GGML_CPU_FP16_TO_FP32(ab->d[2]),
1916	                        __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi2, vl), vl), vl);
1917	                    facc3 = __riscv_vfmacc_vf_f32m2(facc3, GGML_CPU_FP16_TO_FP32(ab->d[3]),
1918	                        __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi3, vl), vl), vl);
1919	                }
1920	                sumf0 = __riscv_vfmacc_vv_f32m2(sumf0, dx, facc0, vl);
1921	                sumf1 = __riscv_vfmacc_vv_f32m2(sumf1, dx, facc1, vl);
1922	                sumf2 = __riscv_vfmacc_vv_f32m2(sumf2, dx, facc2, vl);
1923	                sumf3 = __riscv_vfmacc_vv_f32m2(sumf3, dx, facc3, vl);
1924	            }
1925	            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 0) * bs + (size_t) x * 64, sumf0, vl);
1926	            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 1) * bs + (size_t) x * 64, sumf1, vl);
1927	            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 2) * bs + (size_t) x * 64, sumf2, vl);
1928	            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 3) * bs + (size_t) x * 64, sumf3, vl);
1929	        }
