// ---- Q1_0 row-parallel 64x1 (F4d) -----------------------------------------
// lane j = row j; per column ONE vlm mask load + vsub.vx/vadd.vx,mu = net
// +-y. Zero reductions. zve32f only: fp16 scales are expanded with integer
// bit math (no zvfh), int16 group sums are widened with vsext+vfcvt (no
// vfwcvt.f.x.v - some RTLs reject it). LMUL adapts to VLEN so the 64 fp32
// accumulator lanes exactly fill the machine:
//   VLEN=512 : i16 m2 / f32 m4      VLEN>=1024: i16 m1 / f32 m2

#if defined(__riscv_v_intrinsic)

// Software prefetch of upcoming weight blocks. The gemv/gemm inner loop streams
// block_q1_0x64 sequentially (1152 B = 18 cache lines each); the HW prefetcher
// on this core is shallow (L3C_PFP_LINE_NUM=0, D$ 4 entries), so it cannot run
// far enough ahead to hide the L3/DRAM miss latency that makes the kernel
// load-bound. Pull the block Q1_PREFETCH_DIST ahead into cache explicitly.
// Pure hint: results are unchanged. Needs -march=..._zicbop (else
// __builtin_prefetch is a nop); Q1_PREFETCH_DIST=0 disables it entirely.
// Default 1 (measured best on ax46mpv_fpga_l3: 2.14M -> 1.39M cyc on the K=51
// V-proj node, 1.54x; distances 2/4 were worse - one 18-line block ahead
// already hides the L3/DRAM latency, further lookahead only adds cache/MSHR
// pressure). Other cores can override at build time.
//
// always_inline is load-bearing, not a hint: a prefetch has no observable side
// effect, so whenever the compiler leaves this helper out of line ipa-pure-const
// marks it pure and DCE then deletes every call - no warning, no prefetch left,
// and results stay correct so no test notices. GCC 14.2 does exactly that at
// -Os (CMake MinSizeRel), which cost the whole optimization there. Verify with
// check-prefetch.sh in the repo root: it counts prefetch.r per entry point.
#ifndef Q1_PREFETCH_DIST
#define Q1_PREFETCH_DIST 1
#endif
static inline __attribute__((always_inline))
void q1_prefetch_block(const block_q1_0x64 * bx, int l, int nb) {
#if Q1_PREFETCH_DIST > 0
    const int t = l + Q1_PREFETCH_DIST;
    if (t < nb) {
        const char * p = (const char *) &bx[t];
        for (size_t o = 0; o < sizeof(block_q1_0x64); o += 64) {
            __builtin_prefetch(p + o, 0, 3);
        }
    }
#else
    (void) bx; (void) l; (void) nb;
#endif
}

// exact for normals/+-0; q1_0 scales never carry fp16 subnormals
static inline vfloat32m4_t q1_expand_fp16_64_m4(const ggml_half * p) {
    const size_t vl = 64;
    const vuint32m4_t hz   = __riscv_vzext_vf2_u32m4(__riscv_vle16_v_u16m2((const uint16_t *) p, vl), vl);
    const vuint32m4_t sign = __riscv_vsll_vx_u32m4(__riscv_vand_vx_u32m4(hz, 0x8000, vl), 16, vl);
    vuint32m4_t       mag  = __riscv_vadd_vx_u32m4(
        __riscv_vsll_vx_u32m4(__riscv_vand_vx_u32m4(hz, 0x7FFF, vl), 13, vl), (uint32_t) 112 << 23, vl);
    const vbool8_t ez = __riscv_vmseq_vx_u32m4_b8(__riscv_vand_vx_u32m4(hz, 0x7C00, vl), 0, vl);
    mag               = __riscv_vmerge_vxm_u32m4(mag, 0, ez, vl);
    return __riscv_vreinterpret_v_u32m4_f32m4(__riscv_vor_vv_u32m4(sign, mag, vl));
}

static inline vfloat32m2_t q1_expand_fp16_64_m2(const ggml_half * p) {
    const size_t vl = 64;
    const vuint32m2_t hz   = __riscv_vzext_vf2_u32m2(__riscv_vle16_v_u16m1((const uint16_t *) p, vl), vl);
    const vuint32m2_t sign = __riscv_vsll_vx_u32m2(__riscv_vand_vx_u32m2(hz, 0x8000, vl), 16, vl);
    vuint32m2_t       mag  = __riscv_vadd_vx_u32m2(
        __riscv_vsll_vx_u32m2(__riscv_vand_vx_u32m2(hz, 0x7FFF, vl), 13, vl), (uint32_t) 112 << 23, vl);
    const vbool16_t ez = __riscv_vmseq_vx_u32m2_b16(__riscv_vand_vx_u32m2(hz, 0x7C00, vl), 0, vl);
    mag                = __riscv_vmerge_vxm_u32m2(mag, 0, ez, vl);
    return __riscv_vreinterpret_v_u32m2_f32m2(__riscv_vor_vv_u32m2(sign, mag, vl));
}

static void q1_gemv_64x1_vl512(int n, float * s, const void * vx, const block_q8_0 * a_ptr, int nc) {
    const int    nb = n / QK1_0;
    const size_t vl = 64;
    for (int x = 0; x < nc / 64; ++x) {
        const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
        vfloat32m4_t sumf = __riscv_vfmv_v_f_f32m4(0.0f, vl);
        for (int l = 0; l < nb; ++l) {
            q1_prefetch_block(bx, l, nb);
            const vfloat32m4_t dx   = q1_expand_fp16_64_m4(bx[l].d);
            vfloat32m4_t       facc = __riscv_vfmv_v_f_f32m4(0.0f, vl);
            for (int k = 0; k < QK1_0 / QK8_0; ++k) {
                const block_q8_0 * ab = &a_ptr[l * (QK1_0 / QK8_0) + k];
                vint16m2_t sumi = __riscv_vmv_v_x_i16m2(0, vl);
                for (int c = 0; c < QK8_0; ++c) {
                    const int16_t  yc   = ab->qs[c];
                    const vbool8_t sign = __riscv_vlm_v_b8(bx[l].qs[k * QK8_0 + c], vl);
                    sumi = __riscv_vsub_vx_i16m2(sumi, yc, vl);
                    sumi = __riscv_vadd_vx_i16m2_mu(sign, sumi, sumi, (int16_t) (2 * yc), vl);
                }
                facc = __riscv_vfmacc_vf_f32m4(facc, GGML_CPU_FP16_TO_FP32(ab->d),
                    __riscv_vfcvt_f_x_v_f32m4(__riscv_vsext_vf2_i32m4(sumi, vl), vl), vl);
            }
            sumf = __riscv_vfmacc_vv_f32m4(sumf, dx, facc, vl);
        }
        __riscv_vse32_v_f32m4(s + (size_t) x * 64, sumf, vl);
    }
}

static void q1_gemv_64x1_vl1024(int n, float * s, const void * vx, const block_q8_0 * a_ptr, int nc) {
    const int    nb = n / QK1_0;
    const size_t vl = 64;
    for (int x = 0; x < nc / 64; ++x) {
        const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
        vfloat32m2_t sumf = __riscv_vfmv_v_f_f32m2(0.0f, vl);
        for (int l = 0; l < nb; ++l) {
            q1_prefetch_block(bx, l, nb);
            const vfloat32m2_t dx   = q1_expand_fp16_64_m2(bx[l].d);
            vfloat32m2_t       facc = __riscv_vfmv_v_f_f32m2(0.0f, vl);
            for (int k = 0; k < QK1_0 / QK8_0; ++k) {
                const block_q8_0 * ab = &a_ptr[l * (QK1_0 / QK8_0) + k];
                vint16m1_t sumi = __riscv_vmv_v_x_i16m1(0, vl);
                for (int c = 0; c < QK8_0; ++c) {
                    const int16_t   yc   = ab->qs[c];
                    const vbool16_t sign = __riscv_vlm_v_b16(bx[l].qs[k * QK8_0 + c], vl);
                    sumi = __riscv_vsub_vx_i16m1(sumi, yc, vl);
                    sumi = __riscv_vadd_vx_i16m1_mu(sign, sumi, sumi, (int16_t) (2 * yc), vl);
                }
                facc = __riscv_vfmacc_vf_f32m2(facc, GGML_CPU_FP16_TO_FP32(ab->d),
                    __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi, vl), vl), vl);
            }
            sumf = __riscv_vfmacc_vv_f32m2(sumf, dx, facc, vl);
        }
        __riscv_vse32_v_f32m2(s + (size_t) x * 64, sumf, vl);
    }
}

// gemm over the blck_size_interleave=1 x4 activation layout: qs[c*4+m], d[4].
// M-tile = 4 at VLEN>=1024 (~25/32 regs), 2 at VLEN=512 (f32 accs are m4).

static void q1_gemm_64x1_vl512(int n, float * s, size_t bs, const void * vx, const block_q8_0x4 * vy, int nr, int nc) {
    const int    nb   = n / QK1_0;
    const int    nbq8 = n / QK8_0;
    const size_t vl   = 64;
    for (int y = 0; y < nr / 4; ++y) {
        const block_q8_0x4 * a_ptr = vy + (size_t) y * nbq8;
        for (int x = 0; x < nc / 64; ++x) {
            const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
            for (int mh = 0; mh < 4; mh += 2) {
                vfloat32m4_t sumf0 = __riscv_vfmv_v_f_f32m4(0.0f, vl);
                vfloat32m4_t sumf1 = sumf0;
                for (int l = 0; l < nb; ++l) {
                    q1_prefetch_block(bx, l, nb);
                    const vfloat32m4_t dx    = q1_expand_fp16_64_m4(bx[l].d);
                    vfloat32m4_t       facc0 = __riscv_vfmv_v_f_f32m4(0.0f, vl);
                    vfloat32m4_t       facc1 = facc0;
                    for (int k = 0; k < QK1_0 / QK8_0; ++k) {
                        const block_q8_0x4 * ab = &a_ptr[l * (QK1_0 / QK8_0) + k];
                        vint16m2_t sumi0 = __riscv_vmv_v_x_i16m2(0, vl);
                        vint16m2_t sumi1 = sumi0;
                        for (int c = 0; c < QK8_0; ++c) {
                            const vbool8_t sign = __riscv_vlm_v_b8(bx[l].qs[k * QK8_0 + c], vl);
                            const int16_t  a0   = ab->qs[c * 4 + mh + 0];
                            const int16_t  a1   = ab->qs[c * 4 + mh + 1];
                            sumi0 = __riscv_vsub_vx_i16m2(sumi0, a0, vl);
                            sumi0 = __riscv_vadd_vx_i16m2_mu(sign, sumi0, sumi0, (int16_t) (2 * a0), vl);
                            sumi1 = __riscv_vsub_vx_i16m2(sumi1, a1, vl);
                            sumi1 = __riscv_vadd_vx_i16m2_mu(sign, sumi1, sumi1, (int16_t) (2 * a1), vl);
                        }
                        facc0 = __riscv_vfmacc_vf_f32m4(facc0, GGML_CPU_FP16_TO_FP32(ab->d[mh + 0]),
                            __riscv_vfcvt_f_x_v_f32m4(__riscv_vsext_vf2_i32m4(sumi0, vl), vl), vl);
                        facc1 = __riscv_vfmacc_vf_f32m4(facc1, GGML_CPU_FP16_TO_FP32(ab->d[mh + 1]),
                            __riscv_vfcvt_f_x_v_f32m4(__riscv_vsext_vf2_i32m4(sumi1, vl), vl), vl);
                    }
                    sumf0 = __riscv_vfmacc_vv_f32m4(sumf0, dx, facc0, vl);
                    sumf1 = __riscv_vfmacc_vv_f32m4(sumf1, dx, facc1, vl);
                }
                __riscv_vse32_v_f32m4(s + (size_t) (y * 4 + mh + 0) * bs + (size_t) x * 64, sumf0, vl);
                __riscv_vse32_v_f32m4(s + (size_t) (y * 4 + mh + 1) * bs + (size_t) x * 64, sumf1, vl);
            }
        }
    }
}

static void q1_gemm_64x1_vl1024(int n, float * s, size_t bs, const void * vx, const block_q8_0x4 * vy, int nr, int nc) {
    const int    nb   = n / QK1_0;
    const int    nbq8 = n / QK8_0;
    const size_t vl   = 64;
    for (int y = 0; y < nr / 4; ++y) {
        const block_q8_0x4 * a_ptr = vy + (size_t) y * nbq8;
        for (int x = 0; x < nc / 64; ++x) {
            const block_q1_0x64 * bx = (const block_q1_0x64 *) vx + (size_t) x * nb;
            vfloat32m2_t sumf0 = __riscv_vfmv_v_f_f32m2(0.0f, vl);
            vfloat32m2_t sumf1 = sumf0, sumf2 = sumf0, sumf3 = sumf0;
            for (int l = 0; l < nb; ++l) {
                q1_prefetch_block(bx, l, nb);
                const vfloat32m2_t dx    = q1_expand_fp16_64_m2(bx[l].d);
                vfloat32m2_t       facc0 = __riscv_vfmv_v_f_f32m2(0.0f, vl);
                vfloat32m2_t       facc1 = facc0, facc2 = facc0, facc3 = facc0;
                for (int k = 0; k < QK1_0 / QK8_0; ++k) {
                    const block_q8_0x4 * ab = &a_ptr[l * (QK1_0 / QK8_0) + k];
                    vint16m1_t sumi0 = __riscv_vmv_v_x_i16m1(0, vl);
                    vint16m1_t sumi1 = sumi0, sumi2 = sumi0, sumi3 = sumi0;
                    for (int c = 0; c < QK8_0; ++c) {
                        const vbool16_t sign = __riscv_vlm_v_b16(bx[l].qs[k * QK8_0 + c], vl);
                        const int16_t   a0 = ab->qs[c * 4 + 0], a1 = ab->qs[c * 4 + 1];
                        const int16_t   a2 = ab->qs[c * 4 + 2], a3 = ab->qs[c * 4 + 3];
                        sumi0 = __riscv_vsub_vx_i16m1(sumi0, a0, vl);
                        sumi0 = __riscv_vadd_vx_i16m1_mu(sign, sumi0, sumi0, (int16_t) (2 * a0), vl);
                        sumi1 = __riscv_vsub_vx_i16m1(sumi1, a1, vl);
                        sumi1 = __riscv_vadd_vx_i16m1_mu(sign, sumi1, sumi1, (int16_t) (2 * a1), vl);
                        sumi2 = __riscv_vsub_vx_i16m1(sumi2, a2, vl);
                        sumi2 = __riscv_vadd_vx_i16m1_mu(sign, sumi2, sumi2, (int16_t) (2 * a2), vl);
                        sumi3 = __riscv_vsub_vx_i16m1(sumi3, a3, vl);
                        sumi3 = __riscv_vadd_vx_i16m1_mu(sign, sumi3, sumi3, (int16_t) (2 * a3), vl);
                    }
                    facc0 = __riscv_vfmacc_vf_f32m2(facc0, GGML_CPU_FP16_TO_FP32(ab->d[0]),
                        __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi0, vl), vl), vl);
                    facc1 = __riscv_vfmacc_vf_f32m2(facc1, GGML_CPU_FP16_TO_FP32(ab->d[1]),
                        __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi1, vl), vl), vl);
                    facc2 = __riscv_vfmacc_vf_f32m2(facc2, GGML_CPU_FP16_TO_FP32(ab->d[2]),
                        __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi2, vl), vl), vl);
                    facc3 = __riscv_vfmacc_vf_f32m2(facc3, GGML_CPU_FP16_TO_FP32(ab->d[3]),
                        __riscv_vfcvt_f_x_v_f32m2(__riscv_vsext_vf2_i32m2(sumi3, vl), vl), vl);
                }
                sumf0 = __riscv_vfmacc_vv_f32m2(sumf0, dx, facc0, vl);
                sumf1 = __riscv_vfmacc_vv_f32m2(sumf1, dx, facc1, vl);
                sumf2 = __riscv_vfmacc_vv_f32m2(sumf2, dx, facc2, vl);
                sumf3 = __riscv_vfmacc_vv_f32m2(sumf3, dx, facc3, vl);
            }
            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 0) * bs + (size_t) x * 64, sumf0, vl);
            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 1) * bs + (size_t) x * 64, sumf1, vl);
            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 2) * bs + (size_t) x * 64, sumf2, vl);
            __riscv_vse32_v_f32m2(s + (size_t) (y * 4 + 3) * bs + (size_t) x * 64, sumf3, vl);
        }
    }
}

#endif // __riscv_v_intrinsic

void ggml_gemv_q1_0_64x1_q8_0(int n, float * GGML_RESTRICT s, size_t bs, const void * GGML_RESTRICT vx, const void * GGML_RESTRICT vy, int nr, int nc) {
#if defined(__riscv_v_intrinsic)
    assert(n % QK1_0 == 0 && nc % 64 == 0);
    UNUSED(bs); UNUSED(nr);
    const size_t vlenb = __riscv_vlenb();
    if (vlenb >= 128) {
        q1_gemv_64x1_vl1024(n, s, vx, (const block_q8_0 *) vy, nc);
        return;
    }
    if (vlenb >= 64) {
        q1_gemv_64x1_vl512(n, s, vx, (const block_q8_0 *) vy, nc);
        return;
    }
#endif
    ggml_gemv_q1_0_64x1_q8_0_generic(n, s, bs, vx, vy, nr, nc);
}

void ggml_gemm_q1_0_64x1_q8_0(int n, float * GGML_RESTRICT s, size_t bs, const void * GGML_RESTRICT vx, const void * GGML_RESTRICT vy, int nr, int nc) {
#if defined(__riscv_v_intrinsic)
    assert(n % QK1_0 == 0 && nr % 4 == 0 && nc % 64 == 0);
    const size_t vlenb = __riscv_vlenb();
    if (vlenb >= 128) {
        q1_gemm_64x1_vl1024(n, s, bs, vx, (const block_q8_0x4 *) vy, nr, nc);
        return;
    }
    if (vlenb >= 64) {
        q1_gemm_64x1_vl512(n, s, bs, vx, (const block_q8_0x4 *) vy, nr, nc);
        return;
    }
#endif
    ggml_gemm_q1_0_64x1_q8_0_generic(n, s, bs, vx, vy, nr, nc);
}

