#include <stddef.h>

#define QK1_0 128
#define QK8_0 32

typedef uint16_t ggml_half;

typedef struct {
    ggml_half d;                // scale
    uint8_t   qs[QK1_0 / 8];   // 128 sign bits: 1 -> +d, 0 -> -d
} block_q1_0;

typedef struct {
    ggml_half d;                // scale
    int8_t    qs[QK8_0];        // quants in [-127, 127]
