// Q1_0 rdcycle shootout (ace-tq1 style).
//
//   [2] q1_0_dot_vl256  = ORIGINAL production kernel, called once per row per
//                         activation (M*nr calls)
//   [3] q1_0_gemv_64x1  = OPTIMIZED row-parallel GEMV, called once per
//                         activation (masks re-loaded M times)
//   [4] q1_0_gemm_64x1  = GEMM: all M activations in one call, each sign mask
//                         loaded once and reused
//
// Shape: nr=64 rows x n=512 cols x M=4 activations (a 4-token step of the
// 2560x1024 matmul). Correctness is proven in llama.cpp/kernel-lab (QEMU,
// all VLENs); here a cheap smoke check + cycles. Exit code 0 = pass.
//
// Build with -DQ1_HVM=1 to put ALL data (x, bricks, y, outputs) in the HVM
// vector memory (CSR-discovered, see hvm.h) instead of cached RAM - same
// kernels, same checks, only the allocation moves.
//
// Output is raw _write only - NO stdio. vsim's fpga_l3 engine services the
// console MMIO but not the sim_control syscalls stdio init needs (fstat),
// so any printf-family call hangs there. QEMU (-mvh) serves _write too.
#include "q1_0.h"

#include <math.h>

#ifndef Q1_HVM
#define Q1_HVM 0
#endif

#if Q1_HVM
#include "hvm.h"
#endif

static unsigned long rdcycle(void) {
    unsigned long r;
    asm volatile("fence rw, rw" ::: "memory");
    asm volatile("csrr %0, mcycle" : "=r"(r));
    return r;
}

// ---- printf-free console ---------------------------------------------------
extern long _write(int fd, const void * buf, unsigned long count);

static void say(const char * s) {
    unsigned long n = 0;
    while (s[n]) n++;
    _write(1, s, n);
}

static void sayn(unsigned long v) {   // decimal
    char b[21];
    int i = 20;
    do { b[--i] = (char)('0' + v % 10); v /= 10; } while (v);
    _write(1, b + i, (unsigned long)(20 - i));
}

static void sayx(unsigned long v) {   // hex
    char b[17];
    int i = 16;
    do { b[--i] = "0123456789abcdef"[v & 15]; v >>= 4; } while (v);
    say("0x"); _write(1, b + i, (unsigned long)(16 - i));
}

#ifndef Q1_VLEN
#define Q1_VLEN 512
#endif

#define GN  512                  // K (columns)
#define GNR 64                   // rows = one brick group
#define GM  4                    // activation rows (tokens)
#define GNB (GN / QK1_0)         // q1 blocks per weight row
#define GYB (GN / QK8_0)         // q8 blocks per activation row

// all kernel data behind pointers so one build flag moves it RAM <-> HVM;
// out rows: out[m * GNR + r]
static block_q1_0      * x;
static block_q1_0_64x1 * bricks;
static block_q1_0_64d4 * bricks_d4;
static block_q8_0      * y;
static float * out2, * out3, * out4, * out5;

#if !Q1_HVM
static block_q1_0      x_mem[GNR * GNB];
static block_q1_0_64x1 bricks_mem[GNB];
static block_q1_0_64d4 bricks_d4_mem[GNB];
static block_q8_0      y_mem[GM * GYB];
static float           o2_mem[GM * GNR], o3_mem[GM * GNR], o4_mem[GM * GNR], o5_mem[GM * GNR];
#endif

static int place_data(void) {
#if Q1_HVM
    x         = malloc_hvm(sizeof(block_q1_0)      * GNR * GNB, 64);
    bricks    = malloc_hvm(sizeof(block_q1_0_64x1) * GNB,       64);
    bricks_d4 = malloc_hvm(sizeof(block_q1_0_64d4) * GNB,       64);
    y         = malloc_hvm(sizeof(block_q8_0)      * GM * GYB,  64);
    out2   = malloc_hvm(sizeof(float) * GM * GNR, 64);
    out3   = malloc_hvm(sizeof(float) * GM * GNR, 64);
    out4   = malloc_hvm(sizeof(float) * GM * GNR, 64);
    out5   = malloc_hvm(sizeof(float) * GM * GNR, 64);
    if (!x || !bricks || !bricks_d4 || !y || !out2 || !out3 || !out4 || !out5) return 1;
    say("data in HVM: base "); sayx(hvm_csr_base());
    say(" size "); sayn(1ul << (hvm_csr_cfg() & 0xFF)); say(" B\n");
#else
    x = x_mem; bricks = bricks_mem; bricks_d4 = bricks_d4_mem; y = y_mem;
    out2 = o2_mem; out3 = o3_mem; out4 = o4_mem; out5 = o5_mem;
    say("data in RAM (cached)\n");
#endif
    return 0;
}

// cheap deterministic bytes; all scales = fp16 1.0 (cycle count is
// data-independent, so fancy random data buys nothing here)
static uint32_t lcg = 12345;
static uint8_t next_byte(void) { lcg = lcg * 1103515245u + 12345u; return (uint8_t)(lcg >> 16); }

int main(void) {
    say("q1_0 shootout: nr=64 n=512 M=4, built for VLEN=");
    sayn(Q1_VLEN);
    say("\n");
    if (place_data()) { say("HVM overflow\n"); return 2; }

    for (int i = 0; i < GNR * GNB; ++i) {
        x[i].d = 0x3C00; // 1.0
        for (int j = 0; j < QK1_0 / 8; ++j) x[i].qs[j] = next_byte();
    }
    for (int i = 0; i < GM * GYB; ++i) {
        y[i].d = 0x3C00;
        for (int j = 0; j < QK8_0; ++j) y[i].qs[j] = (int8_t)(next_byte() % 255 - 127);
    }
    q1_0_repack_64x1(x, bricks, GNR, GN);
    q1_0_repack_64d4(x, bricks_d4, GNR, GN);
    say("data ready\n");

    // measure: rep0 = cold caches, rep1 = warm
    for (int rep = 0; rep < 2; ++rep) {
        const unsigned long t0 = rdcycle();
        for (int m = 0; m < GM; ++m) {
            for (int r = 0; r < GNR; ++r) {
                q1_0_dot_vl256(GN, &out2[m * GNR + r], x + (size_t)r * GNB, y + (size_t)m * GYB);
            }
        }
        const unsigned long t1 = rdcycle();
        for (int m = 0; m < GM; ++m) {
            q1_0_gemv_64x1(GN, out3 + m * GNR, bricks, y + (size_t)m * GYB, GNR);
        }
        const unsigned long t2 = rdcycle();
        q1_0_gemm_64x1(GN, GM, out4, bricks, y, GNR);
        const unsigned long t3 = rdcycle();
        for (int m = 0; m < GM; ++m) {
            q1_0_gemv_64d4(GN, out5 + m * GNR, bricks_d4, y + (size_t)m * GYB, GNR);
        }
        const unsigned long t4 = rdcycle();

        const unsigned long c2 = t1 - t0, c3 = t2 - t1, c4 = t3 - t2, c5 = t4 - t3;
        const unsigned long nd = GM * GNR;   // output elements
        say("rep"); sayn((unsigned long)rep);
        say(": [2] vl256 x256: "); sayn(c2); say(" cyc ("); sayn(c2 / nd);
        say("/dot) | [3] gemv x4: "); sayn(c3); say(" cyc ("); sayn(c3 / nd);
        say("/dot) | [4] gemm: "); sayn(c4); say(" cyc ("); sayn(c4 / nd);
        say("/dot) | [5] gemv_d4 x4: "); sayn(c5); say(" cyc ("); sayn(c5 / nd);
        say("/dot)\n  speedup x100: gemm vs vl256: "); sayn(c2 * 100ul / c4);
        say(" | gemm vs gemv: "); sayn(c3 * 100ul / c4);
        say(" | gemv vs gemv_d4: "); sayn(c3 * 100ul / c5);
        say("\n");
    }

    // smoke check: same answers (integer part exact: scales are 1.0)
    int failed = 0;
    for (int m = 0; m < GM; ++m) {
        for (int r = 0; r < GNR; ++r) {
            if (fabsf(out2[m * GNR + r] - out3[m * GNR + r]) > 0.5f) {
                say("FAIL gemv m"); sayn((unsigned long)m);
                say(" row "); sayn((unsigned long)r); say("\n");
                failed++;
            }
            if (fabsf(out2[m * GNR + r] - out4[m * GNR + r]) > 0.5f) {
                say("FAIL gemm m"); sayn((unsigned long)m);
                say(" row "); sayn((unsigned long)r); say("\n");
                failed++;
            }
        }
    }
    say(failed ? "FAILED\n" : "ALL PASS\n");
    return failed;
}

// Kernel 5: row-parallel Q1_0 gemv built on nds.vd4dots.vv (XAndesVDot).
//
// nds.vd4dots.vv vd, vs1, vs2 with vtype e32: for every i32 lane,
//   vd[lane] += sum_{k=0..3} vs1[4*lane+k] * vs2[4*lane+k]   (int8 x int8)
// Verified on QEMU -cpu andes-ax45mpv. GCC 14.2 has no intrinsic for it, so
// it goes in as inline asm; GCC re-emits its own vsetvli afterwards, so the
// asm may set vtype freely.
//
// Layout difference vs kernel 3: a lane must hold 4 consecutive columns of
// ONE row, so the sign plane is grouped 4 columns at a time (see q1_0.h).

#include "q1_0.h"

#include <assert.h>
#include <string.h>

#include <riscv_vector.h>

void q1_0_repack_64d4(const block_q1_0 * src, block_q1_0_64d4 * dst, int nr, int n) {
    const int nb = n / QK1_0;
    assert(nr % Q1_NX1_N == 0);
    assert(n % QK1_0 == 0);

    memset(dst, 0, (size_t)(nr / Q1_NX1_N) * nb * sizeof(block_q1_0_64d4));

    for (int r = 0; r < nr; ++r) {
        const int g = r / Q1_NX1_N;
        const int j = r % Q1_NX1_N;
        for (int ib = 0; ib < nb; ++ib) {
            const block_q1_0 * b = &src[(size_t)r * nb + ib];
            block_q1_0_64d4  * o = &dst[(size_t)g * nb + ib];
            o->d[j] = b->d;
            for (int c = 0; c < QK1_0; ++c) {
                const uint8_t bit = (b->qs[c / 8] >> (c % 8)) & 1;
                const int idx = 4 * j + (c % 4);            // bit slot in the plane
                o->qs[c / 4][idx / 8] |= (uint8_t)(bit << (idx % 8));
            }
        }
    }
}

#if Q1_VLEN >= 1024

// e32,m2 at VLEN=1024 = 64 lanes = exactly the 64 rows.
static inline vint32m2_t vd4dots_m2(vint32m2_t acc, vint8m2_t w, vint8m2_t a) {
    asm volatile("vsetvli t0, zero, e32, m2, ta, ma\n\t"
                 "nds.vd4dots.vv %0, %1, %2"
                 : "+vr"(acc) : "vr"(w), "vr"(a) : "t0");
    return acc;
}

static inline vfloat32m2_t d4_expand_fp16_64(const ggml_half * p) {
    const size_t vl = Q1_NX1_N;
    const vuint16m1_t vh = __riscv_vle16_v_u16m1(p, vl);
    const vuint32m2_t hz = __riscv_vzext_vf2_u32m2(vh, vl);
    const vuint32m2_t sign = __riscv_vsll_vx_u32m2(__riscv_vand_vx_u32m2(hz, 0x8000, vl), 16, vl);
    vuint32m2_t mag = __riscv_vadd_vx_u32m2(
        __riscv_vsll_vx_u32m2(__riscv_vand_vx_u32m2(hz, 0x7FFF, vl), 13, vl),
        (uint32_t)112 << 23, vl);
    const vbool16_t ez = __riscv_vmseq_vx_u32m2_b16(__riscv_vand_vx_u32m2(hz, 0x7C00, vl), 0, vl);
    mag = __riscv_vmerge_vxm_u32m2(mag, 0, ez, vl);
    return __riscv_vreinterpret_v_u32m2_f32m2(__riscv_vor_vv_u32m2(sign, mag, vl));
}

void q1_0_gemv_64d4(int n, float * s, const block_q1_0_64d4 * bricks, const block_q8_0 * y, int nr) {
    const int nb = n / QK1_0;
    assert(n % QK1_0 == 0);
    assert(nr % Q1_NX1_N == 0);

    const size_t vl32 = Q1_NX1_N;        // i32 lanes  = rows
    const size_t vl8  = Q1_NX1_N * 4;    // i8 lanes   = rows x 4 columns

    const vint8m2_t vneg1 = __riscv_vmv_v_x_i8m2(-1, vl8);

    for (int g = 0; g < nr / Q1_NX1_N; ++g) {
        const block_q1_0_64d4 * bx = bricks + (size_t)g * nb;

        vfloat32m2_t sumf = __riscv_vfmv_v_f_f32m2(0.0f, vl32);

        for (int ib = 0; ib < nb; ++ib) {
            const vfloat32m2_t dx = d4_expand_fp16_64(bx[ib].d);
            vfloat32m2_t facc = __riscv_vfmv_v_f_f32m2(0.0f, vl32);

            for (int k = 0; k < 4; ++k) {
                const block_q8_0 * yb = &y[ib * 4 + k];
                const float dy = lab_fp16_to_fp32(yb->d);

                vint32m2_t acc = __riscv_vmv_v_x_i32m2(0, vl32);
                for (int c = 0; c < QK8_0; c += 4) {
                    uint32_t w4;
                    __builtin_memcpy(&w4, &yb->qs[c], 4);     // 4 activations, same in every lane
                    const vint8m2_t a =
                        __riscv_vreinterpret_v_i32m2_i8m2(__riscv_vmv_v_x_i32m2((int32_t)w4, vl32));
                    const vbool4_t m  = __riscv_vlm_v_b4(bx[ib].qs[k * (QK8_0 / 4) + c / 4], vl8);
                    const vint8m2_t w = __riscv_vmerge_vxm_i8m2(vneg1, 1, m, vl8);
                    acc = vd4dots_m2(acc, w, a);
                }
                facc = __riscv_vfmacc_vf_f32m2(facc, dy, __riscv_vfcvt_f_x_v_f32m2(acc, vl32), vl32);
            }
            sumf = __riscv_vfmacc_vv_f32m2(sumf, dx, facc, vl32);
        }
        __riscv_vse32_v_f32m2(s + (size_t)g * Q1_NX1_N, sumf, vl32);
    }
}

#else

void q1_0_gemv_64d4(int n, float * s, const block_q1_0_64d4 * bricks, const block_q8_0 * y, int nr) {
    (void)bricks; (void)y;
    for (int i = 0; i < nr; ++i) s[i] = 0.0f;   // VLEN=512 needs m4 lanes; not built
    (void)n;
}

#endif
